// eslint-disable-next-line @typescript-eslint/ban-ts-comment -- generated only by the Cloudflare build
// @ts-ignore `.open-next/worker.js` is generated by the Cloudflare build.
import generatedWorker from "../.open-next/worker.js";
import { getRequestDatabase, withRequestDatabaseClient } from "./server/db";
import { upgradePaymentConnection } from "./server/payment-live-upgrade";
import { dispatchPaymentUpdates } from "./server/payment-update-outbox";
export { OrderPaymentUpdates } from "./payment-updates";

type WorkerEnvironment = {
  ORDER_PAYMENT_UPDATES?: CloudflareEnv["ORDER_PAYMENT_UPDATES"];
  APP_URL?: string;
  INTERNAL_JOB_SECRET?: string;
  HYPERDRIVE?: { connectionString: string };
  [key: string]: unknown;
};

type WorkerContext = {
  waitUntil(promise: Promise<unknown>): void;
};

type GeneratedWorker = {
  fetch(request: Request, env: WorkerEnvironment, context: WorkerContext): Promise<Response>;
};

const app = generatedWorker as GeneratedWorker;

function setRuntimeBindings(env: WorkerEnvironment) {
  (globalThis as typeof globalThis & { tipsyHyperdriveConnectionString?: string }).tipsyHyperdriveConnectionString =
    env.HYPERDRIVE?.connectionString;
  for (const key of [
    "APP_URL", "SESSION_SECRET", "MPESA_ENVIRONMENT", "MPESA_CONSUMER_KEY", "MPESA_CONSUMER_SECRET",
    "MPESA_SHORTCODE", "MPESA_PASSKEY", "MPESA_TRANSACTION_TYPE", "MPESA_CALLBACK_URL", "MPESA_CALLBACK_TOKEN",
    "MPESA_ACCOUNT_REFERENCE", "MPESA_TRANSACTION_STATUS_INITIATOR", "MPESA_TRANSACTION_STATUS_SECURITY_CREDENTIAL",
    "MPESA_TRANSACTION_STATUS_RESULT_URL", "MPESA_TRANSACTION_STATUS_TIMEOUT_URL", "OTP_PROVIDER_URL", "OTP_PROVIDER_TOKEN",
    "OTP_SENDER_ID", "BLESSEDTEXTS_API_KEY", "BLESSEDTEXTS_SENDER_ID", "GOOGLE_CLIENT_ID", "GOOGLE_CLIENT_SECRET", "INTERNAL_JOB_SECRET",
  ]) {
    const value = env[key];
    if (typeof value === "string") process.env[key] = value;
  }
}

async function drainPaymentUpdates(env: WorkerEnvironment) {
  if (!env.ORDER_PAYMENT_UPDATES || !env.HYPERDRIVE?.connectionString) return;
  const namespace = env.ORDER_PAYMENT_UPDATES;
  try {
    await withRequestDatabaseClient(env.HYPERDRIVE.connectionString, () =>
      dispatchPaymentUpdates(getRequestDatabase(), namespace));
  } catch (error) {
    console.error(JSON.stringify({ event: "payment.push_dispatch_failed", errorName: error instanceof Error ? error.name : "Unknown" }));
  }
}

async function fetch(request: Request, env: WorkerEnvironment, context: WorkerContext) {
  setRuntimeBindings(env);
  const url = new URL(request.url);
  const live = url.pathname.match(/^\/api\/v1\/orders\/([^/]+)\/live$/);
  if (live) {
    if (!env.ORDER_PAYMENT_UPDATES) return new Response("Live updates unavailable.", { status: 503 });
    return upgradePaymentConnection(request, decodeURIComponent(live[1]), env.ORDER_PAYMENT_UPDATES,
      typeof env.SESSION_SECRET === "string" ? env.SESSION_SECRET : "");
  }
  const response = env.HYPERDRIVE?.connectionString
    ? await withRequestDatabaseClient(env.HYPERDRIVE.connectionString, () => app.fetch(request, env, context))
    : await app.fetch(request, env, context);
  // Payment/outbox writes have committed before publication. A fresh invocation
  // client avoids sharing socket I/O across request contexts or streaming responses.
  const mayChangePayment = url.pathname.startsWith("/api/v1/payments/")
    || url.pathname.startsWith("/api/v1/checkout/")
    || url.pathname.startsWith("/api/v1/admin/")
    || /\/admin(?:\/|$)/.test(url.pathname)
    || url.hostname === "admin.tipsytheoryy.com";
  if (mayChangePayment && !["GET", "HEAD", "OPTIONS"].includes(request.method)) {
    context.waitUntil(drainPaymentUpdates(env));
  }
  return response;
}

async function runMaintenance(env: WorkerEnvironment, context: WorkerContext) {
  if (!env.APP_URL || !env.INTERNAL_JOB_SECRET) {
    console.error("Maintenance job is not configured: APP_URL or INTERNAL_JOB_SECRET is missing.");
    return;
  }

  const url = new URL("/api/v1/internal/maintenance", env.APP_URL);
  const response = env.HYPERDRIVE?.connectionString
    ? await withRequestDatabaseClient(env.HYPERDRIVE.connectionString, () => app.fetch(
        new Request(url, {
          method: "POST",
          headers: { Authorization: `Bearer ${env.INTERNAL_JOB_SECRET}` },
        }),
        env,
        context,
      ))
    : await app.fetch(
        new Request(url, {
          method: "POST",
          headers: { Authorization: `Bearer ${env.INTERNAL_JOB_SECRET}` },
        }),
        env,
        context,
      );
  if (!response.ok) {
    throw new Error(`Maintenance request failed with ${response.status}.`);
  }
  await drainPaymentUpdates(env);
}

const worker = {
  fetch,
  scheduled(_controller: unknown, env: WorkerEnvironment, context: WorkerContext) {
    setRuntimeBindings(env);
    context.waitUntil(runMaintenance(env, context));
  },
};

export default worker;
